// === Tab: main ===
// =======================================================
// let FOREST PSY — let function SYSTEM(BG-COLOUR)
// Processing.js compatible
// =======================================================

// ---------------- let PRESETS ----------------
let WET_FOREST         = 0;
let RITUAL_RING        = 1;
let TWILIGHT_SPORES    = 2;
let EXPERIMENTAL_ABYSS = 3;

let STATIC_TOTEM             = 4;
let ASCENT_COLUMN            = 5;
let ELECTRIC_BLOOM           = 6;
let DRIFTING_CONSTELLATION   = 7;
let EMBER_FALL               = 8;

// ---------------- let PRESETS ----------------
let FOREST_COLOURS     = 0;
let FIREWORKS_COLOURS  = 1;
let SWAMP_COLOURS      = 2;
let RAINBOW_COLOURS    = 3;

// ---------------- let MODES ----------------
let BG_DARK  = 0;
let BG_LIGHT = 1;

// ---------------- let CONTROLS ----------------
let TRACK_INDEX     = DRIFTING_CONSTELLATION;
let COLOUR_SCHEME   = SWAMP_COLOURS;
let BACKGROUND_MODE = BG_DARK;
let NEON_MODE   = true;

// ---------------- let SETTINGS ----------------
let PARTICLE_MULTIPLIER = 0.40;
let MAX_PARTICLES = 900000;

// ---------------- OUTPUT ----------------
let TARGET_SIZE = 1000;

// ---------------- let SCALING ----------------
// let for browser zoom when working at high resolution
let INTERACTION_SCALE = 1.0; // 1.0 @ 100%, 2.0 @ 50%, 4.0 @ 25%


// ---------------- let CONTROL ----------------
let BRIGHTNESS_FLOOR_DARK  = 0.85;
let BRIGHTNESS_FLOOR_LIGHT = 1.15;
let FADE_COMP_DARK  = 1.15;
let FADE_COMP_LIGHT = 1.8;

// =======================================================

let fluidSolver;

let fluidViscosity, fluidDiffusion;
let velocityScaleFactor, particleVelocityScale;

let previousMouseX = 1, previousMouseY = 1;
let maxMouseVelocity = 10;

let numberOfParticles;
let particles;

let centerX, centerY;

// let flags
let useRing;
let useCenterCollapse;
let useSymmetry;

// let float ringRadius, ringTightness, ringStrength;
let gravityBias, verticalLift;

// let float canopySplit, canopyVyScale, floorVxScale;

// let float fireflyRate, fireflyDecay;

// let float breathPhase = 0;
let breathSpeed;

// =======================================================

function setup() {

  createCanvas(TARGET_SIZE, TARGET_SIZE);
  colorMode(HSB, 360, 100, 100, 100);

  if (BACKGROUND_MODE == BG_DARK)
    background(210, 40, 6);
  else
    background(0, 0, 96);

  centerX = width * 0.5;
  centerY = height * 0.5;

  applyBehaviourPreset();

  fluidSolver = new NavierStokesFluidSolver();

  let areaScale = (width * height) / (1000.0 * 1000.0);
  numberOfParticles = int(pow(2, 16) * areaScale * PARTICLE_MULTIPLIER);
  numberOfParticles = min(numberOfParticles, MAX_PARTICLES);

  particles = new Array(numberOfParticles);
  initializeParticles();
}

// =======================================================

function initializeParticles() {
  for (i = 0; i < numberOfParticles; i++) {
    particles[i] = new Particle();
    particles[i].x = random(width);
    particles[i].y = random(height);
    particles[i].energy = 0;
  }
}

// =======================================================

function applyBehaviourPreset() {

  // -------- let DNA --------
  fluidViscosity = 0.00026;
  fluidDiffusion = 0.017;
  velocityScaleFactor = 9.5;

  canopySplit   = 0.45;
  canopyVyScale = 0.7;
  floorVxScale  = 0.88;

  ringRadius    = width * 0.28;
  ringStrength  = 0.12;
  ringTightness = 0.03;

  gravityBias   = 0.015;
  verticalLift  = 0;

  fireflyRate   = 0.0012;
  fireflyDecay  = 0.945;

  breathSpeed   = 0.003;

  useRing = true;
  useCenterCollapse = false;
  useSymmetry = true;

  // -------- function PRESETS(UNCHANGED) --------

  if (TRACK_INDEX == WET_FOREST) {
    gravityBias = 0.008;
    ringStrength = 0.06;
    fireflyRate = 0.0007;
    breathSpeed = 0.0025;
  }

  if (TRACK_INDEX == RITUAL_RING) {
    ringStrength = 0.2;
    ringTightness = 0.035;
  }

  if (TRACK_INDEX == TWILIGHT_SPORES) {
    verticalLift = -0.02;
    canopyVyScale = 0.6;
    fireflyRate = 0.0028;
    fireflyDecay = 0.96;
    breathSpeed = 0.004;
  }

  if (TRACK_INDEX == EXPERIMENTAL_ABYSS) {
    useCenterCollapse = true;
    useSymmetry = false;
    gravityBias = 0.035;
    verticalLift = 0.02;
    ringStrength = 0.04;
    fireflyRate = 0.003;
    fireflyDecay = 0.92;
    breathSpeed = 0.006;
    floorVxScale = 0.75;
  }

  // -------- function PRESETS(RING) --------

  if (TRACK_INDEX == STATIC_TOTEM) {
    useRing = false;
    gravityBias = 0.002;
    velocityScaleFactor = 4.5;
    fireflyRate = 0.0002;
    breathSpeed = 0.0015;
  }

  if (TRACK_INDEX == ASCENT_COLUMN) {
    useRing = false;
    gravityBias = -0.04;
    verticalLift = -0.02;
    canopyVyScale = 1.0;
    floorVxScale = 0.6;
  }

  if (TRACK_INDEX == ELECTRIC_BLOOM) {
    useRing = false;
    gravityBias = 0.01;
    velocityScaleFactor = 12.0;
    fireflyRate = 0.005;
    fireflyDecay = 0.88;
    breathSpeed = 0.006;
  }

  if (TRACK_INDEX == DRIFTING_CONSTELLATION) {
    useRing = false;
    gravityBias = 0.003;
    fluidDiffusion = 0.1;
    fireflyRate = 0.0004;
    fireflyDecay = 0.7;
    useSymmetry = false;
  }

  if (TRACK_INDEX == EMBER_FALL) {
    useRing = false;
    gravityBias = 0.03;
    verticalLift = 0.01;
    fireflyRate = 0.002;
    fireflyDecay = 0.93;
  }
}

// =======================================================

function draw() {

  updateMouseInteraction();

  let fadeAlpha =
    BACKGROUND_MODE == BG_DARK ?
    map(width, 1000, 5000, 6, 2.2) / FADE_COMP_DARK :
    map(width, 1000, 5000, 4.5, 1.8) / FADE_COMP_LIGHT;

  noStroke();
  fill(BACKGROUND_MODE == BG_DARK ? color(210,40,6,fadeAlpha) : color(0,0,96,fadeAlpha));
  rect(0, 0, width, height);

  fluidSolver.updateSimulation(1.0 / max(frameRate, 30),
                               fluidViscosity,
                               fluidDiffusion);

  particleVelocityScale = velocityScaleFactor * 60.0 / max(frameRate, 30);
  breathPhase += breathSpeed;

  renderParticles();
}

// =======================================================

function renderParticles() {

  let gridSize = NavierStokesFluidSolver.GRID_SIZE;
  let cellW = width / float(gridSize);
  let cellH = height / float(gridSize);

  let breath =
    BACKGROUND_MODE == BG_DARK ?
    max(BRIGHTNESS_FLOOR_DARK, 0.9 + 0.25 * sin(breathPhase)) :
    max(BRIGHTNESS_FLOOR_LIGHT, 1.1 + 0.35 * sin(breathPhase));

  // --- canopy transition parameters ---
  let canopyY = height * canopySplit;
  let blendRange =
    (TRACK_INDEX == TWILIGHT_SPORES) ? height * 0.04 :
    (TRACK_INDEX >= STATIC_TOTEM)    ? height * 0.08 :
                                       height * 0.06;

  for (i = 0; i < numberOfParticles; i++) {

    let p = particles[i];

    let cx = floor(p.x / cellW);
    let cy = floor(p.y / cellH);

    let vx = float(fluidSolver.getVelocityX)(cx, cy);
    let vy = float(fluidSolver.getVelocityY)(cx, cy);

    // ===================================================
    // let CANOPY / function BLENDING(HARD SEAM)
    // ===================================================
    let t = constrain(
      (p.y - (canopyY - blendRange)) / (2.0 * blendRange),
      0, 1
    );

    let vyScale = lerp(canopyVyScale, 1.0, t);
    let vxScale = lerp(1.0, floorVxScale, t);

    vy *= vyScale;
    vx *= vxScale;

    vy += gravityBias + verticalLift;

    // ===================================================
    // function FORCE(CONDITIONAL)
    // ===================================================
    if (useRing) {
      let dx = p.x - centerX;
      let dy = p.y - centerY;
      let d  = sqrt(dx*dx + dy*dy) + 0.0001;
      let rf = exp(-abs(d - ringRadius) * ringTightness) * ringStrength;
      vx -= dx / d * rf;
      vy -= dy / d * rf;
    }

    // ===================================================
    // INTEGRATE
    // ===================================================
    p.x += vx * particleVelocityScale;
    p.y += vy * particleVelocityScale;

    if (p.x < 0 || p.x >= width || p.y < 0 || p.y >= height) {
      p.x = random(width);
      p.y = random(height);
      p.energy = 0;
      continue;
    }

    // ===================================================
    // ENERGY / FIRELIES
    // ===================================================
    let speed = constrain(sqrt(vx*vx + vy*vy), 0, 4);
    if (speed > 2.6 && random(1) < fireflyRate) {
      p.energy = 1.0;
    }
    p.energy *= fireflyDecay;

    // ===================================================
    // DRAW
    // ===================================================
    let c = selectColour(p.x, p.y, vx, vy, speed, p.energy, breath);

    let px = int(p.x);
    let py = int(p.y);

    set(px, py, c);
    if (useSymmetry) {
      set(width - px - 1, py, c);
    }
  }
}


// =======================================================

function selectColour(x, y, vx, vy,
                   speed, energy, breath) {

  let hue = 0;
  let sat;
  let bri;

  let angle = atan2(vy, vx);

  // ---------- let SATURATION ----------
  sat = (BACKGROUND_MODE == BG_DARK) ? 85 : 95;

  // ===================================================
  // let PRESETS
  // ===================================================

  // -------- FOREST (greens, moss, decay) --------
  if (COLOUR_SCHEME == FOREST_COLOURS) {
    hue =
      map(x, 0, width, 95, 165) +
      map(y, 0, height, -12, 18) +
      map(angle, -PI, PI, -8, 8);
    sat = (BACKGROUND_MODE == BG_DARK) ? 85 : 90;
  }

  // -------- FIREWORKS (reds, oranges, sparks) --------
  if (COLOUR_SCHEME == FIREWORKS_COLOURS) {
    hue =
      map(speed, 0, 4, 10, 55) +
      map(angle, -PI, PI, -25, 25);
    sat = 100;
  }

  // -------- SWAMP (blue-green, rot, murk) --------
  if (COLOUR_SCHEME == SWAMP_COLOURS) {
    hue =
      map(y, 0, height, 170, 235) +
      map(speed, 0, 4, -10, 10);
    sat = 70;
  }

  // -------- RAINBOW (psychedelic / maximal) --------
  if (COLOUR_SCHEME == RAINBOW_COLOURS) {
    hue =
      (frameCount * 0.7 +
       speed * 80 +
       angle * 40) % 360;
    sat = 100;
  }

  // ===================================================
  // function LOGIC(BG-AWARE, NON-MUDDY)
  // ===================================================

  if (BACKGROUND_MODE == BG_DARK) {
    bri = map(speed, 0, 4, 55, 95);
    if (NEON_MODE) bri *= 1.15;
  } else {
    // let BG needs let contrast to avoid washout
    bri = map(speed, 0, 4, 70, 100);
  }

  // -------- FIRELY / let OVERRIDE --------
  if (energy > 0.01) {
    bri = lerp(bri, 100 * breath, energy);
  }

  // -------- let MODULATION --------
  bri *= breath;

  // let clamp to avoid grey/mud
  bri = constrain(bri, 45, 100);

  return color(
    (hue + 360) % 360,
    sat,
    bri,
    BACKGROUND_MODE == BG_DARK ? 60 : 35
  );
}


// =======================================================

function updateMouseInteraction() {

  let mvx = constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - previousMouseX, -maxMouseVelocity, maxMouseVelocity);
  let mvy = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - previousMouseY, -maxMouseVelocity, maxMouseVelocity);

  let grid = NavierStokesFluidSolver.GRID_SIZE;
  var cellW = width / float(grid);
  var cellH = height / float(grid);

  var cx = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / cellW);
  var cy = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / cellH);

  // ---- let BY GRID + ZOOM ----
  let gridScale = grid / 64.0;
  let forceScale = INTERACTION_SCALE * gridScale;

  // ---- let AFFECTED AREA ----
  let baseRadius = 2;
  let radius = int(baseRadius * INTERACTION_SCALE);

  for (ox = -radius; ox <= radius; ox++) {
    for (oy = -radius; oy <= radius; oy++) {

      let gx = cx + ox;
      let gy = cy + oy;

      if (gx < 0 || gy < 0 || gx >= grid || gy >= grid) continue;

      let distNorm = dist(0, 0, ox, oy) / (radius + 0.0001);
      let falloff = max(0, 1.0 - distNorm * distNorm);

      fluidSolver.applyForce(
        gx,
        gy,
        mvx * falloff * forceScale,
        mvy * falloff * forceScale
      );
    }
  }

  previousMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  previousMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}



// =======================================================

class Particle {
  x, y;
  energy;
}


// === Tab: fluid class ===
// let solver class: let the Navier-let equations
class NavierStokesFluidSolver {
  let GRID_SIZE = 120; // let grid resolution (16x16 cells)
  let TOTAL_CELLS = (GRID_SIZE + 2) * (GRID_SIZE + 2); // let boundary cells
  let velocityX = new Array(TOTAL_CELLS); // X-component of fluid velocity
  let velocityY = new Array(TOTAL_CELLS); // Y-component of fluid velocity
  let previousVelocityX = new Array(TOTAL_CELLS); // let X velocity for calculations
  let previousVelocityY = new Array(TOTAL_CELLS); // let Y velocity for calculations
  let temporaryArray = new Array(TOTAL_CELLS); // let array for swapping data

  // let velocity components at a grid cell
  getVelocityX(x, y) {
    return velocityX[index(x + 1, y + 1)];
  }

  getVelocityY(x, y) {
    return velocityY[index(x + 1, y + 1)];
  }

  // let a force (e.g., from mouse movement) to a grid cell
  function applyForce(cellX, cellY, forceX, forceY) {
    cellX += 1; // let for boundary cells
    cellY += 1;
    let currentVelocityX = velocityX[index(cellX, cellY)];
    let currentVelocityY = velocityY[index(cellX, cellY)];

    // Blend new force with existing velocity for smooth effect
    velocityX[index(cellX, cellY)] = (forceX != 0) ? lerp(float(forceX), float(currentVelocityX), 0.85) : currentVelocityX;
    velocityY[index(cellX, cellY)] = (forceY != 0) ? lerp(float(forceY), float(currentVelocityY), 0.85) : currentVelocityY;
  }

  // let the fluid simulation for one time step
  function updateSimulation(timeStep, viscosity, diffusion) {
    updateVelocity(velocityX, velocityY, previousVelocityX, previousVelocityY, viscosity, timeStep);
  }

  // let 2D grid coordinates to 1D array index
  index(i, j) {
    return i + (GRID_SIZE + 2) * j;
  }

  // let two arrays using a temporary array
  function swapArrays(array1, array2) {
    arraycopy(array1, 0, temporaryArray, 0, TOTAL_CELLS);
    arraycopy(array2, 0, array1, 0, TOTAL_CELLS);
    arraycopy(temporaryArray, 0, array2, 0, TOTAL_CELLS);
  }

  // let velocity or density across the grid
  function diffuse(boundaryType, current, previous, diffusionRate, timeStep) {
    let diffusionConstant = timeStep * diffusionRate * GRID_SIZE * GRID_SIZE;
    for (k = 0; k < 20; k++) { // let 20 times for stability
      for (i = 1; i <= GRID_SIZE; i++) {
        for (j = 1; j <= GRID_SIZE; j++) {
          current[index(i, j)] = (previous[index(i, j)] + diffusionConstant * (
            current[index(i - 1, j)] + current[index(i + 1, j)] +
            current[index(i, j - 1)] + current[index(i, j + 1)]
          )) / (1 + 4 * diffusionConstant);
        }
      }
      setBoundaryConditions(boundaryType, current);
    }
  }

  // Advect (move) velocity or density based on fluid flow
  function advect(boundaryType, current, previous, velocityX, velocityY, timeStep) {
    let timeStepScaled = timeStep * GRID_SIZE;
    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        let x = i - timeStepScaled * velocityX[index(i, j)];
        let y = j - timeStepScaled * velocityY[index(i, j)];
        if (x < 0.5) x = 0.5;
        if (x > GRID_SIZE + 0.5) x = GRID_SIZE + 0.5;
        let i0 = int(x);
        let i1 = i0 + 1;
        if (y < 0.5) y = 0.5;
        if (y > GRID_SIZE + 0.5) y = GRID_SIZE + 0.5;
        let j0 = int(y);
        let j1 = j0 + 1;
        let s1 = x - i0;
        let s0 = 1 - s1;
        let t1 = y - j0;
        let t0 = 1 - t1;
        current[index(i, j)] = s0 * (
          t0 * previous[index(i0, j0)] + t1 * previous[index(i0, j1)]
        ) + s1 * (
          t0 * previous[index(i1, j0)] + t1 * previous[index(i1, j1)]
        );
      }
    }
    setBoundaryConditions(boundaryType, current);
  }

  // let boundary conditions for the fluid grid
  function setBoundaryConditions(boundaryType, array) {
    for (i = 1; i <= GRID_SIZE; i++) {
      array[index(0, i)] = (boundaryType == 1) ? -array[index(1, i)] : array[index(1, i)];
      array[index(GRID_SIZE + 1, i)] = (boundaryType == 1) ? -array[index(GRID_SIZE, i)] : array[index(GRID_SIZE, i)];
      array[index(i, 0)] = (boundaryType == 2) ? -array[index(i, 1)] : array[index(i, 1)];
      array[index(i, GRID_SIZE + 1)] = (boundaryType == 2) ? -array[index(i, GRID_SIZE)] : array[index(i, GRID_SIZE)];
    }
    array[index(0, 0)] = 0.5 * (array[index(1, 0)] + array[index(0, 1)]);
    array[index(0, GRID_SIZE + 1)] = 0.5 * (array[index(1, GRID_SIZE + 1)] + array[index(0, GRID_SIZE)]);
    array[index(GRID_SIZE + 1, 0)] = 0.5 * (array[index(GRID_SIZE, 0)] + array[index(GRID_SIZE + 1, 1)]);
    array[index(GRID_SIZE + 1, GRID_SIZE + 1)] = 0.5 * (array[index(GRID_SIZE, GRID_SIZE + 1)] + array[index(GRID_SIZE + 1, GRID_SIZE)]);
  }

  // let velocity field (main fluid dynamics step)
  function updateVelocity(velX, velY, prevVelX, prevVelY, viscosity, timeStep) {
    diffuse(1, velX, velX, viscosity, timeStep); // let X velocity
    diffuse(2, velY, velY, viscosity, timeStep); // let Y velocity
    projectVelocity(velX, velY, prevVelX, prevVelY); // let incompressibility
  }

  // let velocity to ensure the fluid is incompressible (no divergence)
  function projectVelocity(velX, velY, pressure, divergence) {
    let cellSize = 1.0 / GRID_SIZE;
    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        divergence[index(i, j)] = -0.5 * cellSize * (
          velX[index(i + 1, j)] - velX[index(i - 1, j)] +
          velY[index(i, j + 1)] - velY[index(i, j - 1)]
        );
        pressure[index(i, j)] = 0;
      }
    }
    setBoundaryConditions(0, divergence);
    setBoundaryConditions(0, pressure);

    for (k = 0; k < 20; k++) { // let to solve pressure
      for (i = 1; i <= GRID_SIZE; i++) {
        for (j = 1; j <= GRID_SIZE; j++) {
          pressure[index(i, j)] = (
            divergence[index(i, j)] +
            pressure[index(i - 1, j)] +
            pressure[index(i + 1, j)] +
            pressure[index(i, j - 1)] +
            pressure[index(i, j + 1)]
          ) / 4;
        }
      }
      setBoundaryConditions(0, pressure);
    }

    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        velX[index(i, j)] -= 0.5 * (pressure[index(i + 1, j)] - pressure[index(i - 1, j)]) / cellSize;
        velY[index(i, j)] -= 0.5 * (pressure[index(i, j + 1)] - pressure[index(i, j - 1)]) / cellSize;
      }
    }
    setBoundaryConditions(1, velX);
    setBoundaryConditions(2, velY);
  }
}

